# run_modified_pars_fims ----
## Setup ----
# Load or prepare any necessary data for testing
data("data_big")
parameters <- setup_default_parameters(data = FIMSFrame(data_big))

## IO correctness ----
test_that("run_modified_pars_fims() works with correct inputs", {
  # inflection_point is a label in both the Maturity and Selectivity modules
  fit <- run_modified_pars_fims(
    new_value = 2.5,
    parameter_name = "inflection_point",
    module_name = "Maturity",
    parameters = parameters,
    data = data_big
  )
  inflection_point <- get_estimates(fit) |>
    dplyr::filter(label == "inflection_point")
  clear()

  #' @description Test that run_modified_pars_fims() changes only the parameter in the module given by module_name.
  expect_equal(
    object = inflection_point[["input"]][inflection_point[["module_name"]] == "Maturity"],
    expected = 2.5
  )
  expect_equal(
    object = sort(inflection_point[["input"]][inflection_point[["module_name"]] == "Selectivity"]),
    expected = sort(dplyr::filter(
      parameters,
      module_name == "Selectivity",
      label == "inflection_point"
    )[["value"]])
  )
})

## Error handling ----
test_that("run_modified_pars_fims() returns correct error messages", {
  #' @description Test that run_modified_pars_fims() errors when the label is not in the module given by module_name.
  expect_error(
    object = run_modified_pars_fims(
      new_value = 13,
      parameter_name = "log_rzero",
      module_name = "Selectivity",
      parameters = parameters,
      data = data_big
    ),
    regexp = "not found in parameters object"
  )

  #' @description Test that run_modified_pars_fims() errors when module_name and label match more than 1 parameter.
  expect_error(
    object = run_modified_pars_fims(
      new_value = 2,
      parameter_name = "inflection_point",
      module_name = "Selectivity",
      parameters = parameters,
      data = data_big
    ),
    regexp = "Multiple parameters"
  )
})
